    private final PersonRepository people;
    private final SettingService settings;
    private final SheetRepository sheets;

    public BulkChangeService(ClaimService service, ClaimRepository claims, PersonRepository people,
            SettingService settings, SheetRepository sheets) {
        this.service = service;
        this.claims = claims;
        this.people = people;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** Open the claims of these ids in list order: people in the order they were added, each person's
     *  claims newest first. So their numbers follow that order. An id not of the sheet is refused. */
    public Result open(String sheetId, String user, Collection<Long> ids) {
        return change(sheetId, user, ids, ClaimStatus.OPEN);
    }

    /** Settle the claims of these ids in list order, each by the rules of settling one, all or nothing:
     *  a claim left PENDING counts as settled, but if any one cannot be settled (or an id is not of the
     *  sheet) none is, every one counts as refused and nothing is written. */
    @Transactional
    public SettleResult settle(String sheetId, String user, Collection<Long> ids) {
        Result result = change(sheetId, user, ids, ClaimStatus.SETTLED);
        if (result.refused() > 0) {
            TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
            return new SettleResult(List.of(), new LinkedHashSet<>(ids).size(), null);
        }
        Integer batch = result.changed().isEmpty() ? null : service.markSettleBatch(sheetId, user, result.changed());
        return new SettleResult(result.changed(), result.refused(), batch);
    }

    /** Move the claims of these ids to another person in list order, each by the rules of moving one;
     *  one that cannot be moved is refused. An id not of the sheet is refused. */
    public Result reassign(String sheetId, String user, Collection<Long> ids, long toPersonId) {
        return each(sheetId, user, ids, id -> service.reassign(sheetId, user, id, toPersonId, true));
    }

    /** Re-date the claims of these ids in list order, each by the rules of re-dating one; one that
     *  cannot be re-dated is refused. An id not of the sheet is refused. */
    public Result redate(String sheetId, String user, Collection<Long> ids, LocalDate date) {
        return each(sheetId, user, ids, id -> service.redate(sheetId, user, id, date));
    }

    private Result change(String sheetId, String user, Collection<Long> ids, ClaimStatus next) {
        return each(sheetId, user, ids, id -> service.changeStatus(sheetId, user, id, next));
    }

    private Result each(String sheetId, String user, Collection<Long> ids, LongFunction<Claim> change) {
        Set<Long> selected = new LinkedHashSet<>(ids);
        if (settings.roleOf(sheetId, user) == Role.VIEWER) {
            return new Result(List.of(), selected.size()); // a viewer changes nothing: each is refused
        }
        if (sheets.isArchived(sheetId)) {
            return new Result(List.of(), selected.size()); // an archived sheet changes nothing: each is refused
        }
        List<Long> ordered = inListOrder(sheetId, selected);
        List<Claim> changed = new ArrayList<>();
        int refused = selected.size() - ordered.size();
        for (long id : ordered) {
            try {
                changed.add(change.apply(id));
            } catch (ResponseStatusException notChanged) {
                refused++;
            }
        }
        return new Result(changed, refused);
    }

    private List<Long> inListOrder(String sheetId, Set<Long> ids) {
        Map<Long, Integer> personOrder = new HashMap<>();
        List<Person> listed = people.findInListOrder(sheetId);
        for (int i = 0; i < listed.size(); i++) personOrder.put(listed.get(i).getId(), i);
        return claims.findBySheetIdOrderByListedDesc(sheetId).stream()
                .filter(c -> ids.contains(c.getId()))
                .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
                .map(Claim::getId)
                .toList();
    }
}
    }

    /** Refuse settling or approving a claim with no proofs whose due is above the proof threshold in force
     *  on the claim's date: its person's grade's then when one is set, else the sheet's (a due of n/a, or
     *  no threshold, needs none). */
    private void refuseIfUnproven(String sheetId, Person person, Claim claim, BigDecimal due) {
        if (due == null || claim.getProofs() > 0) return;
        BigDecimal threshold = settings.proofThreshold(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
        if (threshold != null && due.compareTo(threshold) > 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
                            + "; add a proof before it is settled.");
        }
    }

    /** Refuse opening a claim with an empty note whose due is above the sheet's note threshold in force
     *  on the claim's date (a due of n/a, or no threshold, needs none). */
    private void refuseIfUnnoted(String sheetId, Claim claim, BigDecimal due) {
        if (due == null || (claim.getNote() != null && !claim.getNote().isBlank())) return;
        BigDecimal threshold = settings.noteThreshold(sheetId, claim.getDate());
        if (threshold != null && due.compareTo(threshold) > 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The claim's due is above the note threshold of " + threshold.toPlainString()
                            + "; add a note before it is opened.");
        }
    }

    /** Refuse opening a claim whose period (the one its due-by falls in) caps its person's claims, when
     *  the person already has that many OPEN or PENDING claims in it. The sheet is locked, so two opens
     *  cannot both pass the cap. */
    private void refuseIfCapped(String sheetId, Claim claim) {
        if (claim.getDueBy() == null) return;
        Period period = periodOf(sheetId, claim.getDueBy());
        if (period == null || period.getCap() == null) return;
        long held = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .filter((c) -> !c.getId().equals(claim.getId()) && c.getPersonId().equals(claim.getPersonId())
                        && c.getStatus().isOpen() && c.getDueBy() != null && period.contains(c.getDueBy()))
                .count();
        if (held >= period.getCap()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person already has " + period.getCap()
                    + " open claims in period " + period.getName() + ".");
    /** Open a claim's editor, locking the claim for other users. */
    @PostMapping("/claims/{id}/lock")
    public ClaimView lock(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.lock(sheetId.trim(), SignedInUser.name(user), id));
    }

    /** Cancel a claim's editor, releasing the user's lock on it. */
    @PostMapping("/claims/{id}/unlock")
    public ClaimView unlock(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.unlock(sheetId.trim(), SignedInUser.name(user), id));
    }

    /** Open a draft claim. */
    @PostMapping("/claims/{id}/open")
    public ClaimView open(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.changeStatus(sheetId.trim(), SignedInUser.name(user), id, ClaimStatus.OPEN));
    }

    /** Delete a draft claim. */
    @PostMapping("/claims/{id}/delete")
    public ClaimView delete(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.delete(sheetId.trim(), SignedInUser.name(user), id));
    }

    /** Restore a deleted claim, on the sheet's today it was deleted, as a draft again. */
    @PostMapping("/claims/{id}/restore")
    public ClaimView restore(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.restore(sheetId.trim(), SignedInUser.name(user), id));
    }

    /** Open the selected claims together in list order; each that cannot be opened is left as it is. */
    @PostMapping("/claims/open")
    public BulkOpenView openSelected(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid BulkOpenForm form) {
        BulkChangeService.Result result = bulk.open(sheetId.trim(), SignedInUser.name(user), form.ids());
        return new BulkOpenView(result.changed().size(), result.refused(),
                result.changed().stream().map(ClaimView::of).toList());
    }

    /** Settle the selected claims together in list order; one left pending counts as settled, each
     *  that cannot be settled is left as it is. */
    @PostMapping("/claims/settle")
    public BulkSettleView settleSelected(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid BulkOpenForm form) {
        BulkChangeService.SettleResult result = bulk.settle(sheetId.trim(), SignedInUser.name(user), form.ids());
        return new BulkSettleView(result.changed().size(), result.refused(),
                result.changed().stream().map(ClaimView::of).toList(), result.batch());
    }

    /** Move the selected claims to another person together in list order; each that cannot be moved
     *  is left as it is. */
    @PostMapping("/claims/reassign")
    public BulkReassignView reassignSelected(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid BulkReassignForm form) {
        BulkChangeService.Result result = bulk.reassign(sheetId.trim(), SignedInUser.name(user), form.ids(),
                form.personId());
        return new BulkReassignView(result.changed().size(), result.refused(),
                result.changed().stream().map(ClaimView::of).toList());
    }

    /** Re-date the selected claims together in list order; each that cannot be re-dated is left as it is. */
    @PostMapping("/claims/redate")
    public BulkRedateView redateSelected(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid BulkRedateForm form) {
        BulkChangeService.Result result = bulk.redate(sheetId.trim(), SignedInUser.name(user), form.ids(), form.date());
        return new BulkRedateView(result.changed().size(), result.refused(),
                result.changed().stream().map(ClaimView::of).toList());
    }

    /** Settle an open claim; a clerk's settling above the clerk limit leaves it pending. */
    @PostMapping("/claims/{id}/settle")
    public ClaimView settle(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.changeStatus(sheetId.trim(), SignedInUser.name(user), id, ClaimStatus.SETTLED));
    }

    /** Why a steward rejects a pending claim. */
    public record RejectForm(@NotBlank @Size(max = 200) String reason) {
    }

    /** Approve a pending claim, settling it. */
    @PostMapping("/claims/{id}/approve")
    public ClaimView approve(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return ClaimView.of(service.approve(sheetId.trim(), SignedInUser.name(user), id));
    }

